const TRACKS=['upper','middle','lower','deep'];
export function makeAudioDirector(){
 let context=null,base=null,layer=null,baseGain=null,layerGain=null,enabled=false,volume=.5,current='',lastState=null,voices=new Set(),hidden=false;
 function init(){if(context)return;const C=globalThis.AudioContext||globalThis.webkitAudioContext;if(!C)return;context=new C();base=new Audio();layer=new Audio();base.preload=layer.preload='none';base.loop=layer.loop=true;layer.src='./assets/audio/danger.mp3';baseGain=context.createGain();layerGain=context.createGain();context.createMediaElementSource(base).connect(baseGain).connect(context.destination);context.createMediaElementSource(layer).connect(layerGain).connect(context.destination);baseGain.gain.value=0;layerGain.gain.value=0;}
 function update(s,on,settings={}){lastState=s;enabled=on;volume=settings.volume??.5;if(!on||hidden){base?.pause();layer?.pause();for(const v of [...voices]){v.pause();v._emberRelease?.();}return;}init();if(!context)return;context.resume().catch(()=>{});const track=s.phase==='won'?'won':s.phase==='lost'?'lost':s.rooms[s.pos].type==='checkpoint'?'refuge':TRACKS[s.rooms[s.pos].stage??Math.min(3,s.rooms[s.pos].row)];if(track!==current){current=track;base.src=`./assets/audio/${track}.mp3`;base.currentTime=0;}baseGain.gain.setTargetAtTime(volume*.6,context.currentTime,.35);layerGain.gain.setTargetAtTime(s.phase==='playing'?volume*Math.max(0,(s.noise-3)/9)*.45:0,context.currentTime,.6);base.play().catch(()=>{});if(s.noise>=4&&s.phase==='playing')layer.play().catch(()=>{});else layer.pause();}
 function cue(name,terrain='stone'){if(!enabled||hidden)return;init();if(!context)return;const file=name==='move'?terrain:({relic:'buy',reward:'buy','noise-reveal':'breath','last-reveal':'card',resolve:'card',gather:'card',heartbeat:'breath',rage:'breath',noise:'lure',heard:'bad',impact:'attack',tick:'stone',reveal:'card',charge:'card',chain:'card'}[name]||name);if(['stop','hush','stop-all'].includes(file)){if(file==='stop-all')for(const v of [...voices]){v.pause();v._emberRelease?.();}return;}if(voices.size>=5){const first=voices.values().next().value;first.pause();first._emberRelease?.();}const a=new Audio(`./assets/audio/${['stone','water','shards','moss','attack','buy','card','lure','breath','collapse','win','bad','turn'].includes(file)?file:'card'}.mp3`),gain=context.createGain(),source=context.createMediaElementSource(a);gain.gain.value=volume*(file==='breath'?.35:.6);source.connect(gain).connect(context.destination);voices.add(a);let cleared=false;const clear=()=>{if(cleared)return;cleared=true;voices.delete(a);source.disconnect();gain.disconnect();};a._emberRelease=clear;a.addEventListener('ended',clear,{once:true});a.addEventListener('error',clear,{once:true});a.play().catch(clear);}
 if(typeof document!=='undefined'){document.addEventListener('visibilitychange',()=>{hidden=document.hidden;if(lastState)update(lastState,enabled,{volume});});}
 return {update,cue,status:()=>({track:current,pressure:lastState?.noise||0,enabled,ready:context?.state==='running',basePlaying:!!base&&!base.paused,layerPlaying:!!layer&&!layer.paused,layerGain:layerGain?.gain.value||0,voices:voices.size})};
}
